module.exports = function(RED) {
    
    function getVoiceClient() {
        console.log("[AT Service] Checking config...");

        // Direct .env fallback (most reliable for now)
        if (process.env.AT_USERNAME && process.env.AT_API_KEY) {
            console.log(`✅ Using .env credentials: ${process.env.AT_USERNAME}`);
            const AfricasTalking = require('africastalking');
            return AfricasTalking({
                username: process.env.AT_USERNAME,
                apiKey: process.env.AT_API_KEY
            }).VOICE;
        }

        // Try RED.kumva
        const config = RED.kumva?.atConfig;
        if (config && config.username && config.apiKey) {
            console.log(`✅ Using config node: ${config.username}`);
            const AfricasTalking = require('africastalking');
            return AfricasTalking({
                username: config.username,
                apiKey: config.apiKey
            }).VOICE;
        }

        throw new Error("Africa's Talking config node not properly set. Check credentials or .env file");
    }

    return { getVoiceClient };
};